import json
import re

def invoice_to_json(text):
    lines = text.strip().split('\n')
    result = {}
    items = []
    for line in lines:
        if line.startswith("Invoice #"):
            result['invoice_number'] = line.split('#')[1].strip()
        elif line.startswith("Customer:"):
            result['customer'] = line.split(':',1)[1].strip()
        elif line.startswith("Items:"):
            items_str = line.split(':',1)[1].strip()
            for part in items_str.split(', '):
                m = re.match(r'(.+?)\s+x(\d+)\s+\(\$(\d+)\)', part)
                if m:
                    name, qty, price = m.groups()
                    items.append({'name': name, 'quantity': int(qty), 'unit_price': int(price)})
                else:
                    m2 = re.match(r'(.+?)\s+\(\$(\d+)\)', part)
                    if m2:
                        name, price = m2.groups()
                        items.append({'name': name, 'quantity': 1, 'unit_price': int(price)})
            result['items'] = items
        elif line.startswith("Total:"):
            result['total'] = line.split(':',1)[1].strip()
    return json.dumps(result, indent=2)

